// NaturalLinkAuditing declares automatic auditing for normal lifecycle writes. Register it once through audit.Register.
// Existing observer registration owns dependency construction, duplicate detection and transaction lifetime.
func NaturalLinkAuditing(policy NaturalLinkAuditPolicy) record.Declaration {
	return record.Declare(func(registrar *foundation.Registrar, pool foundation.Key[*database.DB], resolve record.ResolveWriter) error {
		name, err := record.ObserverName[NaturalLink]()
		if err != nil {
			return err
		}
		return RegisterNaturalLinkObserver(registrar, pool, NewNaturalLinkObserver(name), func(resolver foundation.Resolver) (func() NaturalLinkHooks, error) {
			writer, err := resolve(resolver)
			if err != nil {
				return nil, err
			}
			if writer == nil {
				return nil, foundryfault.New(foundryfault.Invalid, "audit writer is not initialized")
			}
			return func() NaturalLinkHooks {
				write := func(ctx context.Context, tx *database.Tx, changes NaturalLinkChanges) error {
					captured, err := changes.Audit(policy)
					if err != nil {
						return err
					}
					return writer.RecordModel(ctx, tx, captured.Entry())
				}
				return NaturalLinkHooks{Created: write, Updated: write, Deleted: write, Restored: write}
			}, nil
		})
	})
}
